  /* ---------- Задания по схемам ---------- */
  function on(x, sim, type) { return x.comps(type).some(function (c) { return x.isOn(sim, c); }); }
  function allOn(x, sim, type) { var l = x.comps(type); return l.length > 0 && l.every(function (c) { return x.isOn(sim, c); }); }
  function has(x) { for (var i = 1; i < arguments.length; i++) { var a = arguments[i]; if (typeof a === 'string') { if (x.count(a) < 1) return false; } else if (x.count(a[0]) < a[1]) return false; } return true; }
  function cur(x, c) { return Math.abs(x.sim.comps[c.id].I); }
  function nominal(x, type, lo, hi) {
    var l = x.comps(type);
    return l.length > 0 && l.every(function (c) { var b = x.sim.comps[c.id].b; return b >= lo && b <= hi; });
  }

